const SPINNER: [char; 8] = ['⣾', '⣽', '⣻', '⢿', '⡿', '⣟', '⣯', '⣷'];

pub struct CyclicProgress {
    max_steps: u64,
    current_step: u64,
}

impl CyclicProgress {
    pub fn new(max_steps: u64) -> Self {
        Self {
            max_steps,
            current_step: 0,
        }
    }

    pub fn next(&mut self) {
        self.current_step += 1;
    }

    pub fn str(&self) -> String {
        let frame = SPINNER[(self.current_step % SPINNER.len() as u64) as usize];
        let percentage = if self.max_steps == 0 {
            0.0
        } else {
            (self.current_step % self.max_steps) as f64 * 100.0 / self.max_steps as f64
        };

        format!("{} {:.1}%", frame, percentage)
    }
}

