        Self::percentage_with_precision(value, 1)
    }

    pub fn percentage_with_precision(value: f32, precision: usize) -> String {
        format!("{:.*}%", precision, value * 100.0)
    }

    pub fn progress(current: u64, total: u64) -> String {
        format!("{}/{}", current, total)
